// URL imports for 3D / HDR assets (see `assetsInclude` in vite.config.ts).
declare module '*.glb' {
  const src: string
  export default src
}
declare module '*.gltf' {
  const src: string
  export default src
}
declare module '*.hdr' {
  const src: string
  export default src
}
declare module '*.exr' {
  const src: string
  export default src
}
declare module '*.ktx2' {
  const src: string
  export default src
}
